  }));

  // Programmatic "(location) (service)" landing pages (lib/marketing/locationLandings.ts).
  for (const slug of LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.7,
    });
  }

  // Region-tier umbrella landing pages above the city matrix (same file) —
  // e.g. /usa-vps-hosting, /europe-game-server-hosting. Slightly higher
  // priority than a single city page since they target more generic,
  // higher-volume queries ("american vps hosting").
  for (const slug of REGION_LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.75,
    });
  }

  // Game family × location landing pages (lib/marketing/gameLocationLandings.ts)
  // — e.g. /singapore-minecraft-server-hosting, /germany-valheim-server-hosting.
  // Slightly lower priority than the flagship single-game pages (0.7-0.8 above)
  // since these are the longer-tail cross-product of the two axes.
  for (const slug of GAME_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.6,
    });
  }

  // General "[Location] VPS/Game Server Hosting" pages for the locations in
  // that same file's GAME_LOCATIONS table that don't already have one via
  // the tables above (Singapore/Germany/Europe are skipped there — already
  // covered by RESERVED_SLUGS / COMBOS / REGION_COMBOS respectively).
  for (const slug of GENERAL_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.7,
    });
  }

  // Published blog posts (model may not be migrated yet — access defensively).
  try {
    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
    const posts = blogModel
      ? await blogModel.findMany({
          where: { published: true },
          select: { slug: true, updatedAt: true },
          orderBy: { publishedAt: "desc" },
        })
      : [];
    for (const p of posts) {
      entries.push({
        url: `${APP_URL}/blog/${p.slug}`,
        lastModified: p.updatedAt,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  } catch {
    // blogPost model not migrated yet — skip.
  }

  // Public free-Minecraft server pages (/servers/[subdomain]) — same opt-in
  // gate as the page itself (isPublic + READY), so the sitemap never points a
  // crawler at a server whose owner hasn't chosen to list it. Uncapped here
  // (unlike the /servers directory page, which caps its display at 48) since
  // a sitemap listing more entries than a page shows is normal and desirable
  // for indexing — every public server should be crawlable even if it's
  // beyond the directory's newest-48 display cap.
  try {
    const freeServers = await db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" },
      select: { subdomain: true, createdAt: true },
    });
    for (const s of freeServers) {
      entries.push({
        url: `${APP_URL}/servers/${s.subdomain}`,
        lastModified: s.createdAt,
        changeFrequency: "weekly",
        priority: 0.5,
      });
    }
  } catch {
    // Defensive, matching the blogPost handling above — should never actually
    // throw since FreeMinecraftServer ships in this same migration.
  }

  // NxLabs — the public mod/plugin catalog's own browse index page (just the
  // one /mods URL). The 45,761+ individual mod detail URLs
  // (lib/mods-catalog.ts's active+upstreamOk filter) are NOT pushed here —
  // they're served through their own chunked sitemap ids above/at
  // lib/sitemap-mods.ts, kept off this file entirely so this sitemap can
  // never approach Google's 50,000-URL cap again regardless of how large the
  // catalogue grows.
  entries.push({ url: `${APP_URL}/mods`, lastModified: now, changeFrequency: "weekly", priority: 0.7 });

  // Pages that exist only on the new marketing site (app/nxm, live at the real
  // URLs since 2026-09-27): every game x region page, the game-host comparison
  // pages, per-game mod hubs, etc. — every exact route the site serves
  // (app/nxm/_data/live-routes.json) that isn't already listed above, so Google
  // can find them. The design package's example blog slug is skipped (it 404s).
  if (process.env.NXM_ROOT === "1") {
    const listed = new Set(entries.map((e) => e.url));
    for (const route of NXM_LIVE_ROUTES.exact) {
      if (route === "/blog/how-to-self-host-vaultwarden-behind-an-nginx-reverse-proxy") continue;
      const url = `${APP_URL}${route === "/" ? "" : route}`;
      if (listed.has(url) || listed.has(`${url}/`)) continue;
      listed.add(url);
      entries.push({ url, lastModified: now, changeFrequency: "weekly", priority: route.split("/").length > 2 ? 0.6 : 0.7 });
    }
  }

  return entries;
}

import { NextResponse } from "next/server";
import { countIndexableMods, modChunkCountFor } from "@/lib/sitemap-mods";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

/**
 * The REAL sitemap index at /sitemap.xml.
 *
 * This is a hand-written Route Handler, not the `sitemap.ts` special-file
 * convention — a deliberate choice, not an oversight. Next.js's
 * `generateSitemaps()` API (used by app/sitemap.ts for the actual URL
 * chunks below) does NOT build a combined index automatically: per the
 * Next.js docs (Generating multiple sitemaps —
 * https://nextjs.org/docs/app/api-reference/file-conventions/metadata/sitemap#generating-multiple-sitemaps),
 * "Your generated sitemaps will be available at /.../sitemap/[id].xml" —
 * full stop. Confirmed against this project's installed next@15.5.21: once
 * a `sitemap.ts` file exports `generateSitemaps()`, Next replaces the flat
 * `/sitemap.xml` route entirely with `/sitemap/[id].xml` — there is no
 * automatic `<sitemapindex>` anywhere. Without this file, nothing would
 * exist at `/sitemap.xml` at all (a real 404), and nothing would tell a
 * crawler how many chunk ids exist or where to find them.
 *
 * `countIndexableMods()`/`modChunkCountFor()` are the exact same functions
 * app/sitemap.ts's own `generateSitemaps()` uses to decide how many mod
 * chunks to produce — imported from the one shared module
 * (lib/sitemap-mods.ts) specifically so this index can never drift out of
 * sync with the real chunk ids app/sitemap.ts actually serves.
 */
export async function GET() {
  const modCount = await countIndexableMods();
  const modChunks = modChunkCountFor(modCount);
  // The build stamp, NOT `new Date()`. A request-time value meant this index
  // claimed all five child sitemaps had changed the moment Google fetched it,
  // every time — the same defect app/sitemap.ts carried, and the reason
  // Search Console had no trustworthy freshness signal to work from.
  const now = new Date(process.env.BUILD_TIME ?? Date.now()).toISOString();

  // ids 0..modChunks — id 0 is the static/marketing sitemap, ids 1..modChunks
  // are the mod URL chunks. Must match app/sitemap.ts's generateSitemaps()
  // exactly (same shared helpers, so it does).
  const sitemapUrls = Array.from({ length: modChunks + 1 }, (_, i) => `${APP_URL}/sitemap/${i}.xml`);

  const body = `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapUrls
    .map((url) => `  <sitemap>\n    <loc>${url}</loc>\n    <lastmod>${now}</lastmod>\n  </sitemap>`)
    .join("\n")}\n</sitemapindex>\n`;

  return new NextResponse(body, {
    headers: {
      "Content-Type": "application/xml",
      "Cache-Control": "public, max-age=0, must-revalidate",
    },
  });
}
import type { Metadata } from "next";
import { SEO, type SeoEntry } from "./registry";

/**
 * Metadata for a new-marketing page, keyed by its PRODUCTION route.
 *
 * - title/description from the SEO registry (seeded from the live site), or
 *   from the page loader's `meta()` when they depend on live data;
 * - canonical = the production route (never the /nxm staging path), so the
 *   staged pages can never compete with the live ones;
 * - OpenGraph/Twitter from the same text (the site-wide opengraph-image
 *   applies unless an image is given);
 * - noindex while the new site is staged; indexable once it replaces the live
 *   routes (NXM_LIVE=1 at launch).
 */
export const NXM_LIVE = process.env.NXM_LIVE === "1";

export type SeoOverride = Partial<SeoEntry> & {
  image?: string;
  type?: "website" | "article";
  /** e.g. "/blog?page=3" — defaults to the route */
  canonical?: string;
  /** search results and other thin variants */
  noindex?: boolean;
  article?: { publishedTime?: string; modifiedTime?: string; authors?: string[]; tags?: string[] };
};

export function nxmMetadata(route: string, over?: SeoOverride): Metadata {
  const base = SEO[route];
  if (!base && !over?.title) throw new Error(`nxm SEO: no registry entry for ${route}`);
  const e = { ...base, ...over } as SeoEntry & SeoOverride;
  if (!e.title || !e.description) throw new Error(`nxm SEO: ${route} is missing a title or description`);
  const title = e.absolute ? { absolute: e.title } : e.title;
  return {
    title,
    description: e.description,
    alternates: { canonical: e.canonical ?? route },
    openGraph: {
      title: e.title,
      description: e.description,
      url: e.canonical ?? route,
      siteName: "Nxeon",
      ...(e.image ? { images: [{ url: e.image }] } : {}),
      ...(e.type === "article" ? { type: "article" as const, ...(e.article ?? {}) } : { type: "website" as const }),
    },
    twitter: { card: "summary_large_image", title: e.title, description: e.description, ...(e.image ? { images: [e.image] } : {}) },
    robots: NXM_LIVE && !e.noindex ? { index: true, follow: true } : NXM_LIVE ? { index: false, follow: true } : { index: false, follow: false, nocache: true },
  };
}

/** Breadcrumb trail for a route: every ancestor that has a registry entry. */
export function crumbs(route: string, leafName?: string): { name: string; path: string }[] {
  const out = [{ name: "Home", path: "/" }];
  const parts = route.split("/").filter(Boolean);
  for (let i = 1; i <= parts.length; i++) {
    const path = "/" + parts.slice(0, i).join("/");
    const isLeaf = i === parts.length;
    const name = isLeaf ? (leafName ?? SEO[path]?.crumb) : SEO[path]?.crumb;
    if (name) out.push({ name, path });
  }
  return out;
}
