  let lastWasAgent = false;
  for (const raw of txt.split(/\r?\n/)) {
    const line = raw.replace(/#.*$/, "").trim();
    if (!line) continue;
    const i = line.indexOf(":");
    if (i < 0) continue;
    const k = line.slice(0, i).trim().toLowerCase();
    const v = line.slice(i + 1).trim();
    if (k === "sitemap") info.sitemaps.push(v);
    else if (k === "user-agent") {
      if (!cur || !lastWasAgent) {
        cur = { agents: [], allow: [], disallow: [] };
        info.groups.push(cur);
      }
      cur.agents.push(v);
      lastWasAgent = true;
      continue;
    } else if (cur && k === "allow") cur.allow.push(v);
    else if (cur && k === "disallow") cur.disallow.push(v);
    lastWasAgent = false;
  }
  return info;
}

/** Is `path` blocked for `agent` ("*" by default)? Longest-match wins, Allow beats Disallow on ties. */
export function robotsBlocks(info: RobotsInfo, path: string, agent = "*"): boolean {
  const g = info.groups.find((x) => x.agents.some((a) => a.toLowerCase() === agent.toLowerCase())) ?? info.groups.find((x) => x.agents.includes("*"));
  if (!g) return false;
  const match = (rule: string) => {
    if (!rule) return -1;
    const re = new RegExp("^" + rule.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*").replace(/\\\$$/, "$"));
    return re.test(path) ? rule.length : -1;
  };
  const a = Math.max(-1, ...g.allow.map(match));
  const d = Math.max(-1, ...g.disallow.map(match));
  return d > a;
}

/**
 * Template buckets used to group scores. Order matters; first match wins.
 * Kept in one place so the audit, the admin page and the docs agree.
 */
export function classifyTemplate(pathname: string): string {
  const p = pathname.replace(/\/+$/, "") || "/";
  if (p === "/") return "home";
  if (p.startsWith("/mods/")) return "mod";
  if (p === "/mods" || p.startsWith("/mods?")) return "mod-hub";
  if (p.startsWith("/blog/")) return "blog-post";
  if (p === "/blog") return "blog-index";
  if (p.startsWith("/tools/")) return "tool";
  if (p.startsWith("/servers/")) return "free-server";
  if (p.startsWith("/legal/")) return "legal";
  if (p.startsWith("/compare") || /^\/vps-vs-|-alternative$|^\/migrate-from-/.test(p)) return "comparison";
  if (/^\/(migrate|move)-/.test(p)) return "migration";
  if (/-server-hosting$|-hosting$/.test(p) && /^\/(usa|us|canada|europe|asia|uk|germany|singapore|australia|japan|india|brazil|france|netherlands|[a-z-]+)-[a-z0-9-]+-(server|vps|game|web|dedicated|forex|reseller)[a-z-]*$/.test(p) && countLocationHints(p)) return "location-landing";
  if (/-server-hosting$/.test(p)) return "game-landing";
  if (/vps|hosting|domains|business-email|block-storage|nxcloud|gaming/.test(p)) return "product";
  return "static";
}

const LOCATION_WORDS = [
  "singapore", "germany", "usa", "canada", "europe", "asia", "uk", "australia", "japan", "india", "brazil", "france", "netherlands",
  "london", "frankfurt", "tokyo", "sydney", "mumbai", "toronto", "dallas", "new-york", "los-angeles", "miami", "chicago", "seattle",
];
function countLocationHints(p: string): boolean {
  const s = p.slice(1);
  return LOCATION_WORDS.some((w) => s.startsWith(w + "-") || s.includes("-" + w + "-") || s.endsWith("-" + w));
}
