import { jsonLdNodes, nodeTypes, validateJsonLd, type PageFacts } from "./parse";

export type Severity = "critical" | "warning" | "info";
export interface Issue {
  code: string;
  severity: Severity;
  message: string;
  /** points deducted from the page score */
  cost: number;
}

export interface FetchFacts {
  url: string;
  status: number;
  /** number of redirects followed to reach the final response */
  redirects: number;
  finalUrl: string;
  xRobotsTag?: string | null;
  ttfbMs?: number;
  htmlBytes?: number;
  contentType?: string | null;
}

export interface ScoreContext {
  /** how many other pages in this run share the same title / description / body fingerprint */
  dupTitle: number;
  dupDescription: number;
  dupBody: number;
  /** is the URL one the sitemap told crawlers to index */
  inSitemap: boolean;
  /** broken internal links found by the (sampled) link check; undefined = not checked */
  brokenLinks?: number;
  /** the site's canonical origin, e.g. https://nxeon.cloud */
  origin: string;
}

export const TITLE_MIN = 25;
export const TITLE_MAX = 62;
export const DESC_MIN = 70;
export const DESC_MAX = 165;
/** below this many words of visible main-content text a page is "thin" */
export const THIN_WORDS = 150;

const sev = (cost: number): Severity => (cost >= 15 ? "critical" : cost >= 5 ? "warning" : "info");

/** Normalise a URL for self-canonical comparison (no hash, no trailing slash except root, lowercase host). */
export function normUrl(u: string, origin?: string): string {
  try {
    const x = new URL(u, origin);
    x.hash = "";
    let p = x.pathname.replace(/\/+$/, "") || "/";
    if (p === "/") p = "";
    return `${x.protocol}//${x.host.toLowerCase()}${p}${x.search}`;
  } catch {
    return u;
  }
}

export function scorePage(fetch: FetchFacts, facts: PageFacts | null, ctx: ScoreContext): { score: number; issues: Issue[] } {
  const issues: Issue[] = [];
  const add = (code: string, message: string, cost: number) => issues.push({ code, severity: sev(cost), message, cost });

  if (fetch.status >= 500 || fetch.status === 0) {
    add("http-error", `server error (HTTP ${fetch.status})`, 100);
    return { score: 0, issues };
  }
  if (fetch.status >= 400) {
    add("http-error", `HTTP ${fetch.status} for a URL listed in the sitemap`, 100);
    return { score: 0, issues };
  }
  if (fetch.redirects > 0) add("redirect", `sitemap URL redirects (${fetch.redirects} hop${fetch.redirects > 1 ? "s" : ""}) to ${fetch.finalUrl}`, fetch.redirects > 1 ? 20 : 12);
  if (!facts) {
    add("not-html", "response was not HTML", 30);
    return { score: Math.max(0, 100 - 30), issues };
  }

  const robots = `${facts.robotsMeta ?? ""} ${fetch.xRobotsTag ?? ""}`.toLowerCase();
  if (robots.includes("noindex")) {
    add("noindex", ctx.inSitemap ? "noindex page is listed in the sitemap" : "page is noindex", ctx.inSitemap ? 40 : 0);
  }

  // canonical
  if (!facts.canonical) add("canonical-missing", "no rel=canonical", 15);
  else {
    const self = normUrl(fetch.finalUrl, ctx.origin);
    const canon = normUrl(facts.canonical, ctx.origin);
    if (canon !== self) add("canonical-mismatch", `canonical points to ${facts.canonical}, not this URL`, 12);
    if (!/^https?:\/\//i.test(facts.canonical)) add("canonical-relative", "canonical is not an absolute URL", 4);
  }

  // title
  const t = facts.title?.trim() ?? "";
  if (!t) add("title-missing", "missing <title>", 20);
  else {
    if (t.length < TITLE_MIN) add("title-short", `title is ${t.length} chars (<${TITLE_MIN})`, 4);
    if (t.length > TITLE_MAX + 8) add("title-long", `title is ${t.length} chars; will be truncated in results (>${TITLE_MAX})`, 5);
    else if (t.length > TITLE_MAX) add("title-long", `title is ${t.length} chars (>${TITLE_MAX})`, 2);
    if (ctx.dupTitle > 0) add("title-duplicate", `title shared with ${ctx.dupTitle} other page${ctx.dupTitle > 1 ? "s" : ""}`, 8);
  }

  // description
  const d = facts.description?.trim() ?? "";
  if (!d) add("desc-missing", "missing meta description", 15);
  else {
    if (d.length < DESC_MIN) add("desc-short", `description is ${d.length} chars (<${DESC_MIN})`, 4);
    if (d.length > DESC_MAX + 15) add("desc-long", `description is ${d.length} chars (>${DESC_MAX})`, 4);
    if (ctx.dupDescription > 0) add("desc-duplicate", `description shared with ${ctx.dupDescription} other page${ctx.dupDescription > 1 ? "s" : ""}`, 6);
  }

  // headings
  if (facts.h1.length === 0) add("h1-missing", "no <h1>", 12);
  else if (facts.h1.length > 1) add("h1-multiple", `${facts.h1.length} <h1> elements`, 4);
  let prev = 0;
  for (const h of facts.headings) {
    if (prev && h.level > prev + 1) {
      add("heading-skip", `heading level jumps h${prev} to h${h.level}`, 2);
      break;
    }
    prev = h.level;
  }

  // structured data
  if (facts.jsonLd.length === 0) add("jsonld-missing", "no JSON-LD structured data", 5);
  else {
    const probs = validateJsonLd(facts.jsonLd);
    const parseErrs = probs.filter((p) => p.type === "(parse)");
    if (parseErrs.length) add("jsonld-invalid", `JSON-LD does not parse: ${parseErrs[0].message}`, 15);
    const other = probs.filter((p) => p.type !== "(parse)");
    if (other.length) add("jsonld-problems", `JSON-LD: ${other.slice(0, 3).map((p) => `${p.type} ${p.message}`).join("; ")}`, Math.min(9, other.length * 3));
  }

  // social
  const missingOg = ["title", "description", "image"].filter((k) => !facts.og[k]);
  if (missingOg.length) add("og-missing", `og:${missingOg.join(", og:")} missing`, Math.min(6, missingOg.length * 2));
  if (!facts.twitter.card) add("twitter-missing", "no twitter:card", 2);

  // images
  const noAlt = facts.images.filter((i) => i.alt === null).length;
  if (noAlt) add("img-alt-missing", `${noAlt} image${noAlt > 1 ? "s" : ""} without an alt attribute`, Math.min(8, noAlt));
  const noDims = facts.images.filter((i) => !i.width || !i.height).length;
  if (noDims > 2) add("img-dims-missing", `${noDims} images without width/height (layout-shift risk)`, Math.min(4, noDims));

  // content depth
  if (facts.wordCount < THIN_WORDS) add("thin-content", `only ${facts.wordCount} words of main content`, 10);
  else if (facts.wordCount < 300) add("light-content", `${facts.wordCount} words of main content`, 3);
  if (ctx.dupBody > 0) add("near-duplicate", `body text is a near-duplicate of ${ctx.dupBody} other page${ctx.dupBody > 1 ? "s" : ""} in this run`, Math.min(15, 5 + ctx.dupBody));

  // basics
  if (!facts.lang) add("lang-missing", "<html lang> missing", 2);
  if (!facts.viewport) add("viewport-missing", "no viewport meta", 6);

  // links
  const internal = facts.links.filter((l) => /^\/(?!\/)/.test(l.href) || l.href.startsWith(ctx.origin)).length;
  if (internal < 3) add("few-internal-links", `only ${internal} internal links`, 5);
  if (ctx.brokenLinks) add("broken-links", `${ctx.brokenLinks} broken internal link${ctx.brokenLinks > 1 ? "s" : ""}`, Math.min(12, ctx.brokenLinks * 4));

  // hreflang sanity (only when present)
  if (facts.hreflang.length) {
    const self = normUrl(fetch.finalUrl, ctx.origin);
    if (!facts.hreflang.some((h) => normUrl(h.href, ctx.origin) === self)) add("hreflang-no-self", "hreflang set has no self-reference", 4);
  }

  if (fetch.ttfbMs && fetch.ttfbMs > 1500) add("slow-ttfb", `TTFB ${fetch.ttfbMs}ms`, fetch.ttfbMs > 3000 ? 10 : 5);
  if (fetch.htmlBytes && fetch.htmlBytes > 600_000) add("heavy-html", `HTML is ${(fetch.htmlBytes / 1024).toFixed(0)} KB`, 5);

  const total = issues.reduce((s, i) => s + i.cost, 0);
  return { score: Math.max(0, Math.min(100, 100 - total)), issues };
}

/** Structured-data types present on a page (for coverage tables). */
export function schemaTypes(facts: PageFacts): string[] {
  const set = new Set<string>();
  for (const n of jsonLdNodes(facts.jsonLd)) for (const t of nodeTypes(n)) set.add(t);
  return [...set].sort();
}

// ── Speed ──────────────────────────────────────────────────────────────────

export interface SpeedMetrics {
  lcpMs: number | null;
  cls: number | null;
  /** total blocking time proxy: sum of long-task time over 50ms */
  tbtMs: number | null;
  transferKb: number | null;
  ttfbMs: number | null;
}

/** Linear interpolation: 100 at <= good, 0 at >= poor. */
function band(v: number, good: number, poor: number): number {
  if (v <= good) return 100;
  if (v >= poor) return 0;
  return Math.round(100 * (1 - (v - good) / (poor - good)));
}

/**
 * Speed score 0-100 from measured lab metrics, using Google's published
 * Core Web Vitals "good"/"poor" thresholds as the 100/0 anchors. Only metrics
 * that were actually measured contribute (weights are renormalised).
 */
export function speedScore(m: SpeedMetrics): number | null {
  const parts: [number, number][] = [];
  if (m.lcpMs != null) parts.push([band(m.lcpMs, 2500, 4000), 0.4]);
  if (m.cls != null) parts.push([band(m.cls, 0.1, 0.25), 0.25]);
  if (m.tbtMs != null) parts.push([band(m.tbtMs, 200, 600), 0.2]);
  if (m.transferKb != null) parts.push([band(m.transferKb, 1500, 5000), 0.15]);
  if (!parts.length) return null;
  const w = parts.reduce((s, p) => s + p[1], 0);
  return Math.round(parts.reduce((s, p) => s + p[0] * p[1], 0) / w);
}

// ── Near-duplicate fingerprints ────────────────────────────────────────────

/** 5-word shingles hashed to 32-bit ints; returns a MinHash-ish sample (sorted smallest 64). */
export function fingerprint(text: string): number[] {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(Boolean);
  if (words.length < 5) return [];
  const hashes = new Set<number>();
  for (let i = 0; i + 5 <= words.length; i++) {
    const s = words.slice(i, i + 5).join(" ");
    let h = 2166136261;
    for (let j = 0; j < s.length; j++) {
      h ^= s.charCodeAt(j);
      h = Math.imul(h, 16777619);
    }
    hashes.add(h >>> 0);
  }
  return [...hashes].sort((a, b) => a - b).slice(0, 64);
}

export function similarity(a: number[], b: number[]): number {
  if (!a.length || !b.length) return 0;
  const sb = new Set(b);
  let inter = 0;
  for (const x of a) if (sb.has(x)) inter++;
  return inter / Math.min(a.length, b.length);
}
