cd /opt/nxeon-wt-seo/lib/seo-audit && cat > run.ts <<'E'
/**
 * The audit engine: crawl a sitemap sample from a base URL, score every page
 * and template. Pure network + parsing — no database, so the CLI, the worker
 * sweep and the admin "run now" control all share it. Persistence lives in
 * persist.ts.
 */
import { parseHtml, type PageFacts } from "./parse";
import { classifyTemplate, parseRobots, parseSitemapXml, robotsBlocks, type RobotsInfo } from "./sitemap";
import { fingerprint, normUrl, schemaTypes, scorePage, similarity, speedScore, type FetchFacts, type Issue, type SpeedMetrics } from "./score";

export interface AuditOptions {
  baseUrl: string;
  /** max pages sampled per template (stratified evenly across the sitemap order) */
  perTemplate?: number;
  /** hard cap on total pages fetched */
  maxPages?: number;
  concurrency?: number;
  /** pages (spread across templates) to measure with Chromium; 0 disables */
  speedSample?: number;
  /** distinct internal link targets to health-check */
  linkCheckLimit?: number;
  /** max child sitemaps to open (each is one request) */
  maxSitemaps?: number;
  userAgent?: string;
  onProgress?: (msg: string) => void;
  signal?: AbortSignal;
}

export interface PageResult {
  url: string;
  template: string;
  status: number;
  redirects: number;
  finalUrl: string;
  score: number;
  issues: Issue[];
  title: string | null;
  titleLen: number | null;
  descLen: number | null;
  wordCount: number | null;
  schema: string[];
  ttfbMs: number | null;
  speed?: (SpeedMetrics & { score: number | null }) | null;
}

export interface SitemapFinding {
  code: string;
  severity: "critical" | "warning" | "info";
  message: string;
}

export interface SitemapReport {
  indexUrl: string;
  children: { url: string; status: number; urls: number; bytes: number; lastmodDistinct: number; error?: string }[];
  totalUrls: number;
  uniqueUrls: number;
  byTemplate: Record<string, number>;
  findings: SitemapFinding[];
  /** url → template for every url seen (kept for sampling; not persisted) */
  all: { url: string; lastmod?: string; priority?: string }[];
}

export interface TemplateSummary {
  template: string;
  sitemapUrls: number;
  sampled: number;
  avgScore: number;
  minScore: number;
  topIssues: { code: string; pages: number; message: string }[];
  avgSpeed: number | null;
}

export interface AuditResult {
  baseUrl: string;
  startedAt: string;
  finishedAt: string;
  robots: { status: number; sitemaps: string[]; blocksAll: boolean; info: RobotsInfo | null };
  sitemap: SitemapReport;
  pages: PageResult[];
  templates: TemplateSummary[];
  avgScore: number;
  avgSpeed: number | null;
  topIssues: { code: string; pages: number; message: string }[];
}

const UA = "NxeonSeoAudit/1.0 (+https://nxeon.cloud)";

async function get(url: string, ua: string, redirect: "follow" | "manual" = "manual", maxHops = 6) {
  const t0 = Date.now();
  let cur = url;
  let hops = 0;
  for (;;) {
    const res = await fetch(cur, { redirect: "manual", headers: { "user-agent": ua, accept: "text/html,application/xml,*/*" }, signal: AbortSignal.timeout(45_000) });
    const ttfb = Date.now() - t0;
    const loc = res.headers.get("location");
    if (redirect === "manual" && res.status >= 300 && res.status < 400 && loc && hops < maxHops) {
      cur = new URL(loc, cur).toString();
      hops++;
      await res.arrayBuffer().catch(() => undefined);
      continue;
    }
    return { res, hops, finalUrl: cur, ttfb };
  }
}

async function pool<T, R>(items: T[], n: number, fn: (x: T, i: number) => Promise<R>): Promise<R[]> {
  const out: R[] = new Array(items.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(n, items.length) }, async () => {
      while (next < items.length) {
        const i = next++;
        out[i] = await fn(items[i], i);
      }
    }),
  );
  return out;
}

const rebase = (u: string, base: string) => {
  try {
    const x = new URL(u);
    const b = new URL(base);
    x.protocol = b.protocol;
    x.host = b.host;
    return x.toString();
  } catch {
    return u;
  }
};

export async function auditSitemaps(o: AuditOptions, robots: RobotsInfo | null): Promise<SitemapReport> {
  const ua = o.userAgent ?? UA;
  const base = o.baseUrl.replace(/\/$/, "");
  const indexUrl = `${base}/sitemap.xml`;
  const findings: SitemapFinding[] = [];
  const rep: SitemapReport = { indexUrl, children: [], totalUrls: 0, uniqueUrls: 0, byTemplate: {}, findings, all: [] };
  const idx = await get(indexUrl, ua, "follow").catch((e) => ({ err: e as Error }));
  if ("err" in idx || idx.res.status !== 200) {
    findings.push({ code: "sitemap-unreachable", severity: "critical", message: `${indexUrl} → ${"err" in idx ? idx.err.message : idx.res.status}` });
    return rep;
  }
  const xml = await idx.res.text();
  const parsed = parseSitemapXml(xml);
  let childUrls = parsed.kind === "index" ? parsed.entries.map((e) => rebase(e.loc, base)) : [indexUrl];
  const maxSm = o.maxSitemaps ?? 40;
  if (childUrls.length > maxSm) {
    findings.push({ code: "sitemap-children-truncated", severity: "info", message: `index lists ${childUrls.length} sitemaps; only the first ${maxSm} were opened` });
    childUrls = childUrls.slice(0, maxSm);
  }
  if (parsed.kind === "index" && parsed.entries.length) {
    const lm = new Set(parsed.entries.map((e) => e.lastmod));
    if (lm.size === 1 && parsed.entries.length > 1) findings.push({ code: "index-lastmod-identical", severity: "info", message: `all ${parsed.entries.length} child sitemaps carry the same <lastmod>` });
  }

  const seen = new Map<string, number>();
  for (const cu of childUrls) {
    o.onProgress?.(`sitemap ${cu}`);
    let status = 0;
    let body = "";
    let error: string | undefined;
    try {
      const r = parsed.kind === "index" ? await get(cu, ua, "follow") : { res: idx.res, hops: 0, finalUrl: cu, ttfb: 0 };
      status = r.res.status;
      body = parsed.kind === "index" ? await r.res.text() : xml;
    } catch (e) {
      error = (e as Error).message;
    }
    const child = parseSitemapXml(body);
    const lms = new Set(child.entries.map((e) => e.lastmod?.slice(0, 19)));
    const bytes = Buffer.byteLength(body);
    rep.children.push({ url: cu, status, urls: child.entries.length, bytes, lastmodDistinct: lms.size, error });
    if (status !== 200) findings.push({ code: "sitemap-child-error", severity: "critical", message: `${cu} returned ${status || error} — crawlers drop the whole file` });
    else if (child.entries.length === 0) findings.push({ code: "sitemap-child-empty", severity: "warning", message: `${cu} is empty` });
    if (child.entries.length > 50_000) findings.push({ code: "sitemap-over-50k", severity: "critical", message: `${cu} has ${child.entries.length} URLs (limit 50,000)` });
    if (bytes > 50 * 1024 * 1024) findings.push({ code: "sitemap-over-50mb", severity: "critical", message: `${cu} is ${(bytes / 1048576).toFixed(1)} MB (limit 50 MB)` });
    if (child.entries.length > 200 && lms.size === 1) findings.push({ code: "lastmod-uniform", severity: "warning", message: `${cu}: all ${child.entries.length} URLs share one <lastmod> — crawlers learn to ignore it` });
    for (const e of child.entries) {
      const u = rebase(e.loc, base);
      seen.set(u, (seen.get(u) ?? 0) + 1);
      rep.all.push({ url: u, lastmod: e.lastmod, priority: e.priority });
    }
  }
  rep.totalUrls = rep.all.length;
  rep.uniqueUrls = seen.size;
  const dups = [...seen.entries()].filter(([, n]) => n > 1);
  if (dups.length) findings.push({ code: "sitemap-duplicates", severity: "warning", message: `${dups.length} URLs listed more than once (e.g. ${dups[0][0]})` });
  const pri = new Set(rep.all.map((e) => e.priority));
  if (pri.size > 4) findings.push({ code: "priority-noise", severity: "info", message: `${pri.size} distinct <priority> values — Google ignores priority/changefreq; they are noise` });
  const trailing = rep.all.filter((e) => /\/[^/]+\/$/.test(new URL(e.url).pathname)).length;
  if (trailing) findings.push({ code: "trailing-slash-mix", severity: "warning", message: `${trailing} sitemap URLs end in "/" (the rest do not)` });
  if (robots) {
    const blocked = rep.all.filter((e) => robotsBlocks(robots, new URL(e.url).pathname)).length;
    if (blocked) findings.push({ code: "sitemap-blocked-by-robots", severity: "critical", message: `${blocked} sitemap URLs are disallowed in robots.txt` });
  }
  for (const e of rep.all) {
    const t = classifyTemplate(new URL(e.url).pathname);
    rep.byTemplate[t] = (rep.byTemplate[t] ?? 0) + 1;
  }
  return rep;
}

function stratify<T>(items: T[], n: number): T[] {
  if (items.length <= n) return items;
  const step = items.length / n;
  return Array.from({ length: n }, (_, i) => items[Math.floor(i * step)]);
}

export async function runAudit(o: AuditOptions): Promise<AuditResult> {
  const startedAt = new Date().toISOString();
  const ua = o.userAgent ?? UA;
  const base = o.baseUrl.replace(/\/$/, "");
  const origin = new URL(base).origin;
  const log = o.onProgress ?? (() => undefined);

  // robots
  let robotsInfo: RobotsInfo | null = null;
  let robotsStatus = 0;
  try {
    const r = await get(`${base}/robots.txt`, ua, "follow");
    robotsStatus = r.res.status;
    if (r.res.status === 200) robotsInfo = parseRobots(await r.res.text());
  } catch {
    /* reported via status 0 */
  }
  const blocksAll = !!robotsInfo && robotsBlocks(robotsInfo, "/");

  const sitemap = await auditSitemaps(o, robotsInfo);
  if (robotsStatus !== 200) sitemap.findings.push({ code: "robots-missing", severity: "critical", message: `robots.txt returned ${robotsStatus || "no response"}` });
  if (blocksAll) sitemap.findings.push({ code: "robots-blocks-all", severity: "critical", message: "robots.txt disallows the entire site" });
  if (robotsInfo && !robotsInfo.sitemaps.length) sitemap.findings.push({ code: "robots-no-sitemap", severity: "warning", message: "robots.txt has no Sitemap: line" });

  // sample
  const byT = new Map<string, string[]>();
  const sitemapSet = new Set<string>();
  for (const e of sitemap.all) {
    sitemapSet.add(normUrl(e.url));
    const t = classifyTemplate(new URL(e.url).pathname);
    if (!byT.has(t)) byT.set(t, []);
    byT.get(t)!.push(e.url);
  }
  const per = o.perTemplate ?? 25;
  let sample = [...byT.entries()].flatMap(([t, urls]) => stratify([...new Set(urls)], per).map((u) => ({ url: u, template: t })));
  if (o.maxPages && sample.length > o.maxPages) sample = stratify(sample, o.maxPages);
  log(`sampled ${sample.length} pages across ${byT.size} templates (${sitemap.uniqueUrls} sitemap URLs)`);

  // fetch + parse
  type Raw = { url: string; template: string; fetch: FetchFacts; facts: PageFacts | null };
  let done = 0;
  const raws = await pool(sample, o.concurrency ?? 6, async (s): Promise<Raw> => {
    if (o.signal?.aborted) throw new Error("aborted");
    try {
      const { res, hops, finalUrl, ttfb } = await get(s.url, ua);
      const ct = res.headers.get("content-type");
      const body = res.status === 200 && /html/i.test(ct ?? "") ? await res.text() : (await res.arrayBuffer().catch(() => undefined), "");
      const facts = body ? parseHtml(body) : null;
      if (++done % 25 === 0) log(`fetched ${done}/${sample.length}`);
      return { url: s.url, template: s.template, facts, fetch: { url: s.url, status: res.status, redirects: hops, finalUrl, xRobotsTag: res.headers.get("x-robots-tag"), ttfbMs: ttfb, htmlBytes: Buffer.byteLength(body), contentType: ct } };
    } catch {
      return { url: s.url, template: s.template, facts: null, fetch: { url: s.url, status: 0, redirects: 0, finalUrl: s.url } };
    }
  });

  // duplicate detection within template
  const dupT = new Map<string, number>();
  const dupD = new Map<string, number>();
  for (const r of raws) {
    if (!r.facts) continue;
    const kt = `${r.template}|${r.facts.title?.trim().toLowerCase()}`;
    const kd = `${r.template}|${r.facts.description?.trim().toLowerCase()}`;
    if (r.facts.title) dupT.set(kt, (dupT.get(kt) ?? 0) + 1);
    if (r.facts.description) dupD.set(kd, (dupD.get(kd) ?? 0) + 1);
  }
  const prints = raws.map((r) => (r.facts ? fingerprint(r.facts.text) : []));
  const dupBody = raws.map(() => 0);
  const byTpl = new Map<string, number[]>();
  raws.forEach((r, i) => {
    if (!byTpl.has(r.template)) byTpl.set(r.template, []);
    byTpl.get(r.template)!.push(i);
  });
  for (const idxs of byTpl.values()) {
    for (let a = 0; a < idxs.length; a++)
      for (let b = a + 1; b < idxs.length; b++) {
        if (similarity(prints[idxs[a]], prints[idxs[b]]) >= 0.9) {
          dupBody[idxs[a]]++;
          dupBody[idxs[b]]++;
        }
      }
  }

  // link health (distinct internal targets, bounded)
  const linkStatus = new Map<string, number>();
  const targets = new Map<string, number>();
  for (const r of raws)
    for (const l of r.facts?.links ?? []) {
      if (!/^\/(?!\/)/.test(l.href) && !l.href.startsWith(origin)) continue;
      const u = normUrl(l.href, origin).replace(/[?#].*$/, "");
      if (/\.(png|jpe?g|svg|webp|avif|css|js|ico|woff2?)$/i.test(u) || /\/(api|dashboard|admin)(\/|$)/.test(u)) continue;
      targets.set(u, (targets.get(u) ?? 0) + 1);
    }
  const limit = o.linkCheckLimit ?? 150;
  const toCheck = [...targets.entries()].sort((a, b) => b[1] - a[1]).slice(0, limit).map(([u]) => u);
  await pool(toCheck, 6, async (u) => {
    try {
      const r = await fetch(u, { method: "HEAD", redirect: "manual", headers: { "user-agent": ua }, signal: AbortSignal.timeout(20_000) });
      linkStatus.set(u, r.status === 405 ? 200 : r.status);
    } catch {
      linkStatus.set(u, 0);
    }
  });

  // speed
  let speedByUrl = new Map<string, SpeedMetrics & { score: number | null }>();
  if ((o.speedSample ?? 0) > 0) {
    try {
      const { measureSpeed } = await import("./speed");
      const picks = stratify(
        [...byTpl.entries()].map(([, idxs]) => raws[idxs[Math.floor(idxs.length / 2)]]).filter((r) => r.fetch.status === 200),
        o.speedSample!,
      );
      log(`measuring speed on ${picks.length} pages`);
      speedByUrl = await measureSpeed(picks.map((p) => p.fetch.finalUrl), ua, log);
      // key by original URL
      for (const p of picks) if (speedByUrl.has(p.fetch.finalUrl)) speedByUrl.set(p.url, speedByUrl.get(p.fetch.finalUrl)!);
    } catch (e) {
      log(`speed measurement skipped: ${(e as Error).message}`);
    }
  }

  const pages: PageResult[] = raws.map((r, i) => {
    let broken = 0;
    for (const l of r.facts?.links ?? []) {
      if (!/^\/(?!\/)/.test(l.href) && !l.href.startsWith(origin)) continue;
      const st = linkStatus.get(normUrl(l.href, origin).replace(/[?#].*$/, ""));
      if (st !== undefined && (st === 0 || st >= 400)) broken++;
    }
    const { score, issues } = scorePage(r.fetch, r.facts, {
      dupTitle: r.facts?.title ? Math.max(0, (dupT.get(`${r.template}|${r.facts.title.trim().toLowerCase()}`) ?? 1) - 1) : 0,
      dupDescription: r.facts?.description ? Math.max(0, (dupD.get(`${r.template}|${r.facts.description.trim().toLowerCase()}`) ?? 1) - 1) : 0,
      dupBody: dupBody[i],
      inSitemap: sitemapSet.has(normUrl(r.url)),
      brokenLinks: broken,
      origin,
    });
    const sp = speedByUrl.get(r.url);
    return {
      url: r.url,
      template: r.template,
      status: r.fetch.status,
      redirects: r.fetch.redirects,
      finalUrl: r.fetch.finalUrl,
      score,
      issues,
      title: r.facts?.title ?? null,
      titleLen: r.facts?.title?.length ?? null,
      descLen: r.facts?.description?.length ?? null,
      wordCount: r.facts?.wordCount ?? null,
      schema: r.facts ? schemaTypes(r.facts) : [],
      ttfbMs: r.fetch.ttfbMs ?? null,
      speed: sp ?? null,
    };
  });

  return finish(base, startedAt, { status: robotsStatus, sitemaps: robotsInfo?.sitemaps ?? [], blocksAll, info: robotsInfo }, sitemap, pages);
}

export function summarise(pages: PageResult[], sitemap: SitemapReport): { templates: TemplateSummary[]; avgScore: number; avgSpeed: number | null; topIssues: { code: string; pages: number; message: string }[] } {
  const agg = (ps: PageResult[]) => {
    const m = new Map<string, { pages: number; message: string }>();
    for (const p of ps) for (const i of p.issues) {
      const cur = m.get(i.code);
      m.set(i.code, { pages: (cur?.pages ?? 0) + 1, message: cur?.message ?? i.message });
    }
    return [...m.entries()].map(([code, v]) => ({ code, ...v })).sort((a, b) => b.pages - a.pages);
  };
  const by = new Map<string, PageResult[]>();
  for (const p of pages) {
    if (!by.has(p.template)) by.set(p.template, []);
    by.get(p.template)!.push(p);
  }
  const mean = (xs: number[]) => (xs.length ? Math.round((xs.reduce((a, b) => a + b, 0) / xs.length) * 10) / 10 : 0);
  const templates = [...by.entries()]
    .map(([template, ps]) => {
      const sp = ps.map((p) => p.speed?.score).filter((x): x is number => x != null);
      return {
        template,
        sitemapUrls: sitemap.byTemplate[template] ?? 0,
        sampled: ps.length,
        avgScore: mean(ps.map((p) => p.score)),
        minScore: Math.min(...ps.map((p) => p.score)),
        topIssues: agg(ps).slice(0, 5),
        avgSpeed: sp.length ? mean(sp) : null,
      };
    })
    .sort((a, b) => a.avgScore - b.avgScore);
  // Site score weights each template by its share of the sitemap so one tiny
  // template cannot dominate (nor a 65k-URL one be hidden by a 5-page one).
  const w = templates.map((t) => Math.max(t.sitemapUrls, 1));
  const avgScore = templates.length ? Math.round((templates.reduce((s, t, i) => s + t.avgScore * w[i], 0) / w.reduce((a, b) => a + b, 0)) * 10) / 10 : 0;
  const sp = pages.map((p) => p.speed?.score).filter((x): x is number => x != null);
  return { templates, avgScore, avgSpeed: sp.length ? mean(sp) : null, topIssues: agg(pages).slice(0, 12) };
}

function finish(baseUrl: string, startedAt: string, robots: AuditResult["robots"], sitemap: SitemapReport, pages: PageResult[]): AuditResult {
  return { baseUrl, startedAt, finishedAt: new Date().toISOString(), robots, sitemap, pages, ...summarise(pages, sitemap) };
}

export function toMarkdown(r: AuditResult): string {
  const L: string[] = [];
  L.push(`# SEO audit — ${r.baseUrl}`, "", `Run ${r.startedAt} → ${r.finishedAt}. ${r.pages.length} pages sampled of ${r.sitemap.uniqueUrls} sitemap URLs.`, "");
  L.push(`**Site score: ${r.avgScore}/100** (sitemap-share weighted)${r.avgSpeed != null ? ` · **speed: ${r.avgSpeed}/100** (lab, sampled)` : ""}`, "");
  L.push("## Sitemap", "", "| file | status | URLs | KB | distinct lastmod |", "|---|---|---|---|---|");
  for (const c of r.sitemap.children) L.push(`| ${c.url} | ${c.status || c.error} | ${c.urls} | ${(c.bytes / 1024).toFixed(0)} | ${c.lastmodDistinct} |`);
  L.push("", ...(r.sitemap.findings.length ? r.sitemap.findings.map((f) => `- **${f.severity}** \`${f.code}\` ${f.message}`) : ["- no findings"]), "");
  L.push("## Templates (worst first)", "", "| template | sitemap URLs | sampled | avg | min | speed | top issues |", "|---|---|---|---|---|---|---|");
  for (const t of r.templates) L.push(`| ${t.template} | ${t.sitemapUrls} | ${t.sampled} | ${t.avgScore} | ${t.minScore} | ${t.avgSpeed ?? "—"} | ${t.topIssues.slice(0, 3).map((i) => `${i.code}×${i.pages}`).join(", ")} |`);
  L.push("", "## Top issues", "", ...r.topIssues.map((i) => `- \`${i.code}\` on ${i.pages} pages — ${i.message}`), "");
  const worst = [...r.pages].sort((a, b) => a.score - b.score).slice(0, 15);
  L.push("## Worst pages", "", ...worst.map((p) => `- ${p.score} — ${p.url} (${p.template}) ${p.issues.slice(0, 3).map((i) => i.code).join(", ")}`), "");
  return L.join("\n");
}
E
cat > speed.ts <<'E'
/**
 * Lab speed measurement with headless Chromium (Playwright). LCP and CLS come
 * from PerformanceObserver buffered entries; TBT is approximated from
 * longtask entries (sum of time beyond 50ms); transfer is the sum of
 * PerformanceResourceTiming.transferSize + the document. These are LAB proxies
 * measured on this server's own CPU, not field data — they are for relative
 * comparison and regression alerts, not for quoting as real-user numbers.
 */
import { speedScore, type SpeedMetrics } from "./score";

export async function measureSpeed(urls: string[], ua: string, log: (m: string) => void = () => undefined): Promise<Map<string, SpeedMetrics & { score: number | null }>> {
  const { chromium } = await import("playwright");
  const out = new Map<string, SpeedMetrics & { score: number | null }>();
  const browser = await chromium.launch({ headless: true });
  try {
    for (const url of urls) {
      const ctx = await browser.newContext({ userAgent: ua, viewport: { width: 412, height: 823 }, deviceScaleFactor: 1.75, isMobile: true });
      const page = await ctx.newPage();
      await page.addInitScript(() => {
        const w = window as unknown as { __m: { lcp: number | null; cls: number; tbt: number } };
        w.__m = { lcp: null, cls: 0, tbt: 0 };
        try {
          new PerformanceObserver((l) => {
            const e = l.getEntries();
            w.__m.lcp = e[e.length - 1].startTime;
          }).observe({ type: "largest-contentful-paint", buffered: true });
          new PerformanceObserver((l) => {
            for (const e of l.getEntries() as unknown as { value: number; hadRecentInput: boolean }[]) if (!e.hadRecentInput) w.__m.cls += e.value;
          }).observe({ type: "layout-shift", buffered: true });
          new PerformanceObserver((l) => {
            for (const e of l.getEntries()) if (e.duration > 50) w.__m.tbt += e.duration - 50;
          }).observe({ type: "longtask", buffered: true });
        } catch {
          /* unsupported entry type */
        }
      });
      try {
        await page.goto(url, { waitUntil: "load", timeout: 60_000 });
        await page.waitForTimeout(2500);
        const m = await page.evaluate(() => {
          const w = window as unknown as { __m: { lcp: number | null; cls: number; tbt: number } };
          const nav = performance.getEntriesByType("navigation")[0] as PerformanceNavigationTiming | undefined;
          const res = performance.getEntriesByType("resource") as PerformanceResourceTiming[];
          const bytes = res.reduce((s, r) => s + (r.transferSize || 0), 0) + (nav?.transferSize || 0);
          return { lcp: w.__m.lcp, cls: w.__m.cls, tbt: w.__m.tbt, bytes, ttfb: nav ? nav.responseStart : null };
        });
        const sm: SpeedMetrics = {
          lcpMs: m.lcp != null ? Math.round(m.lcp) : null,
          cls: Math.round(m.cls * 1000) / 1000,
          tbtMs: Math.round(m.tbt),
          transferKb: Math.round(m.bytes / 1024),
          ttfbMs: m.ttfb != null ? Math.round(m.ttfb) : null,
        };
        out.set(url, { ...sm, score: speedScore(sm) });
        log(`speed ${url}: LCP ${sm.lcpMs}ms CLS ${sm.cls} TBT ${sm.tbtMs}ms ${sm.transferKb}KB`);
      } catch (e) {
        log(`speed ${url} failed: ${(e as Error).message}`);
      } finally {
        await ctx.close();
      }
    }
  } finally {
    await browser.close();
  }
  return out;
}
