/**
 * SEO audit CLI.
 *   npx tsx scripts/seo-audit.ts --base http://localhost:3120 [--per-template 25] [--max-pages 400]
 *        [--speed 6] [--links 150] [--json out.json] [--md out.md] [--persist]
 * --persist writes SeoAuditRun/SeoAuditPage rows to DATABASE_URL (the sandbox DB when
 * run from an agent worktree). Exit code 2 if the site score < --fail-under.
 */
import { writeFileSync } from "node:fs";
import { runAudit, toMarkdown } from "../lib/seo-audit/run";

function arg(name: string, def?: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : def;
}

async function main() {
  const base = arg("base", "http://localhost:3000")!;
  const opts = {
    baseUrl: base,
    perTemplate: Number(arg("per-template", "25")),
    maxPages: Number(arg("max-pages", "0")) || undefined,
    speedSample: Number(arg("speed", "0")),
    linkCheckLimit: Number(arg("links", "150")),
    concurrency: Number(arg("concurrency", "6")),
    onProgress: (m: string) => console.error(`[seo-audit] ${m}`),
  };
  let result;
  if (process.argv.includes("--persist")) {
    const { runAndPersistAudit } = await import("../lib/seo-audit/persist");
    const r = await runAndPersistAudit(opts, "cli");
    result = r.result;
    console.error(`[seo-audit] persisted run ${r.runId}; regressions: ${r.regressions.length}`);
    process.on("exit", () => undefined);
  } else result = await runAudit(opts);
  const json = arg("json");
  const md = arg("md");
  if (json) writeFileSync(json, JSON.stringify({ ...result, sitemap: { ...result.sitemap, all: undefined } }, null, 1));
  if (md) writeFileSync(md, toMarkdown(result));
  console.log(toMarkdown(result));
  const fail = Number(arg("fail-under", "0"));
  if (fail && result.avgScore < fail) process.exit(2);
  process.exit(0);
}
main().catch((e) => {
  console.error(e);
  process.exit(1);
});
