import { db } from "@/lib/db";
import { runAudit, type AuditOptions, type AuditResult } from "./run";

export interface RegressionAlert {
  kind: "site" | "template";
  name: string;
  previous: number;
  current: number;
}

/** Score drop (points) between consecutive runs that triggers an alert. */
export const REGRESSION_THRESHOLD = 3;

export function detectRegressions(
  prev: { avgScore: number | null; summary: unknown } | null,
  cur: { avgScore: number; templates: { template: string; avgScore: number }[] },
): RegressionAlert[] {
  if (!prev) return [];
  const out: RegressionAlert[] = [];
  if (prev.avgScore != null && prev.avgScore - cur.avgScore >= REGRESSION_THRESHOLD) out.push({ kind: "site", name: "site", previous: prev.avgScore, current: cur.avgScore });
  const pt = ((prev.summary as { templates?: { template: string; avgScore: number }[] } | null)?.templates ?? []);
  for (const t of cur.templates) {
    const p = pt.find((x) => x.template === t.template);
    if (p && p.avgScore - t.avgScore >= REGRESSION_THRESHOLD) out.push({ kind: "template", name: t.template, previous: p.avgScore, current: t.avgScore });
  }
  return out;
}

/** Run an audit and persist it as SeoAuditRun + SeoAuditPage rows. Returns the run id. */
export async function runAndPersistAudit(opts: AuditOptions, trigger: "manual" | "weekly" | "cli", existingRunId?: string): Promise<{ runId: string; result: AuditResult; regressions: RegressionAlert[] }> {
  const run = existingRunId
    ? await db.seoAuditRun.update({ where: { id: existingRunId }, data: { status: "RUNNING" } })
    : await db.seoAuditRun.create({ data: { baseUrl: opts.baseUrl, trigger } });
  try {
    const prev = await db.seoAuditRun.findFirst({ where: { status: "DONE", baseUrl: opts.baseUrl, id: { not: run.id } }, orderBy: { startedAt: "desc" } });
    const result = await runAudit(opts);
    const regressions = detectRegressions(prev, result);
    await db.seoAuditPage.createMany({
      data: result.pages.map((p) => ({
        runId: run.id,
        url: p.url.slice(0, 1000),
        template: p.template,
        status: p.status,
        redirectChain: p.redirects,
        score: p.score,
        issues: p.issues as unknown as object,
        title: p.title?.slice(0, 300) ?? null,
        titleLen: p.titleLen,
        descLen: p.descLen,
        wordCount: p.wordCount,
        lcpMs: p.speed?.lcpMs ?? null,
        cls: p.speed?.cls ?? null,
        transferKb: p.speed?.transferKb ?? null,
        ttfbMs: p.ttfbMs,
        speedScore: p.speed?.score ?? null,
      })),
    });
    await db.seoAuditRun.update({
      where: { id: run.id },
      data: {
        status: "DONE",
        finishedAt: new Date(),
        pagesChecked: result.pages.length,
        avgScore: result.avgScore,
        avgSpeed: result.avgSpeed,
        sitemapUrls: result.sitemap.uniqueUrls,
        summary: {
          templates: result.templates,
          topIssues: result.topIssues,
          sitemap: { children: result.sitemap.children, findings: result.sitemap.findings, byTemplate: result.sitemap.byTemplate, totalUrls: result.sitemap.totalUrls },
          robots: { status: result.robots.status, sitemaps: result.robots.sitemaps, blocksAll: result.robots.blocksAll },
          regressions,
        } as unknown as object,
      },
    });
    return { runId: run.id, result, regressions };
  } catch (e) {
    await db.seoAuditRun.update({ where: { id: run.id }, data: { status: "FAILED", finishedAt: new Date(), error: String((e as Error).message).slice(0, 500) } });
    throw e;
  }
}
