"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { writeAudit } from "./audit";

/** Admin: queue an SEO audit. The worker (worker/seo-audit.ts) picks it up; idempotent while one is pending. */
export async function queueSeoAudit(): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("platform");
  const pending = await db.seoAuditRun.findFirst({ where: { status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending) return { ok: true };
  const baseUrl = (process.env.SEO_AUDIT_BASE_URL ?? process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  const run = await db.seoAuditRun.create({ data: { baseUrl, trigger: "manual", status: "QUEUED" } });
  await writeAudit({ actorId: (admin as { id?: string })?.id ?? null, action: "seo.audit.queue", target: run.id }).catch(() => undefined);
  revalidatePath("/admin/seo/audit");
  return { ok: true };
}
