import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { SeoAuditRunButton } from "@/components/admin/seo/SeoAuditRunButton";

export const dynamic = "force-dynamic";

type TemplateRow = { template: string; sitemapUrls: number; sampled: number; avgScore: number; minScore: number; avgSpeed: number | null; topIssues: { code: string; pages: number }[] };
type Finding = { code: string; severity: string; message: string };

const tone = (s: number): "green" | "amber" | "red" => (s >= 85 ? "green" : s >= 70 ? "amber" : "red");

function Spark({ values }: { values: number[] }) {
  if (values.length < 2) return <span className="text-xs text-slate-600">needs 2+ runs</span>;
  const w = 220;
  const h = 40;
  const pts = values.map((v, i) => `${((i / (values.length - 1)) * w).toFixed(1)},${(h - (v / 100) * h).toFixed(1)}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} role="img" aria-label="site score over recent runs">
      <polyline points={pts} fill="none" stroke="currentColor" strokeWidth="2" className="text-brand-400" />
    </svg>
  );
}

export default async function SeoAuditPage() {
  await requireArea("platform");
  const runs = await db.seoAuditRun.findMany({ orderBy: { startedAt: "desc" }, take: 20 });
  const done = runs.filter((r) => r.status === "DONE");
  const latest = done[0];
  const prev = done[1];
  const busy = runs.some((r) => r.status === "QUEUED" || r.status === "RUNNING");
  const summary = (latest?.summary ?? null) as { templates?: TemplateRow[]; sitemap?: { findings?: Finding[] }; regressions?: { kind: string; name: string; previous: number; current: number }[] } | null;
  const prevTemplates = new Map(((prev?.summary as { templates?: TemplateRow[] } | null)?.templates ?? []).map((t) => [t.template, t.avgScore]));
  const worstPages = latest ? await db.seoAuditPage.findMany({ where: { runId: latest.id }, orderBy: { score: "asc" }, take: 15 }) : [];

  return (
    <div className="space-y-6">
      <PageHeader title="SEO audit" sub="Weekly crawl of a stratified sitemap sample: status, canonicals, titles, descriptions, headings, structured data, images, duplicates and lab speed. Scores are computed from what was fetched — nothing is estimated.">
        <SeoAuditRunButton busy={busy} />
      </PageHeader>
      <div className="flex gap-2 text-xs">
        <Link href="/admin/seo" className="text-brand-300 underline">Search opportunities</Link>
      </div>

      {!latest ? (
        <EmptyState title="No audit has completed yet" sub="Press “Run audit now”, or wait for the weekly worker sweep." />
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div className="card py-3">
              <div className="flex items-center gap-2 text-2xl font-semibold text-white">{latest.avgScore?.toFixed(1)}<Badge tone={tone(latest.avgScore ?? 0)}>{prev?.avgScore != null && latest.avgScore != null ? `${(latest.avgScore - prev.avgScore >= 0 ? "+" : "")}${(latest.avgScore - prev.avgScore).toFixed(1)}` : "first run"}</Badge></div>
              <div className="text-[11px] uppercase tracking-wide text-slate-500">Site score</div>
            </div>
            <div className="card py-3">
              <div className="text-2xl font-semibold text-white">{latest.avgSpeed?.toFixed(0) ?? "—"}</div>
              <div className="text-[11px] uppercase tracking-wide text-slate-500">Lab speed (sampled)</div>
            </div>
            <div className="card py-3">
              <div className="text-2xl font-semibold text-white">{latest.pagesChecked.toLocaleString()}</div>
              <div className="text-[11px] uppercase tracking-wide text-slate-500">Pages checked</div>
            </div>
            <div className="card py-3">
              <div className="text-2xl font-semibold text-white">{latest.sitemapUrls?.toLocaleString() ?? "—"}</div>
              <div className="text-[11px] uppercase tracking-wide text-slate-500">Sitemap URLs · {timeAgo(latest.startedAt)}</div>
            </div>
          </div>

          <div className="card">
            <div className="mb-2 text-sm font-semibold text-slate-200">Score trend (last {done.length} runs)</div>
            <Spark values={[...done].reverse().map((r) => r.avgScore ?? 0)} />
          </div>

          {summary?.regressions?.length ? (
            <div className="card border-red-500/30 bg-red-500/[0.06]">
              <p className="text-sm font-semibold text-red-200">Regressions since the previous run</p>
              <ul className="mt-1 text-xs text-slate-300">
