cd /opt/nxeon-wt-seo && cat > lib/seo-index-policy.ts <<'E'
/**
 * Index-quality policy for the programmatic page families (see
 * docs/SEO-AUDIT-2026-10.md §4). The evidence, measured on 2026-10-01:
 *  - game × location pages share 81–87% of 5-word shingles with their siblings
 *    (same game, different place) — a near-duplicate cluster of ~700 URLs;
 *  - only 23 of them received a single search-referred human visit in 30 days;
 *  - 64,853 mod pages vs 28 with a search-referred visit in 30 days.
 * Google's scaled-content-abuse policy targets exactly "many pages, little
 * unique value, made for search". So the SITEMAP (the list of pages we ask
 * Google to prioritise) is limited to pages with a real reason to exist:
 *   - game × location: the location has a real datacenter ("core"), or the page
 *     has earned a search/AI-referred human visit in the last 90 days;
 *   - mods: real downloads at or above a floor.
 * Pages outside the sitemap stay crawlable and indexable (no traffic is
 * removed by this alone). Hard `noindex` on the tail is a separate, OFF-by-
 * default switch the owner flips after reading the audit. All knobs are
 * `Setting` rows:
 *   seo_mod_sitemap_min_downloads   default 10000   (0 = list every mod)
 *   seo_mod_noindex_below_downloads default 100     (0 = never noindex a mod)
 *   seo_gameloc_sitemap_mode        default demand  ("all" = list every combo)
 *   seo_gameloc_noindex_tail        default false   (true = noindex tail combos)
 */
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { GAME_LOCATION_COMBOS, GAME_LOCATIONS_BY_SLUG } from "@/lib/marketing/gameLocationLandings";

export interface SeoPolicy {
  modSitemapMinDownloads: number;
  modNoindexBelowDownloads: number;
  gameLocSitemapMode: "demand" | "all";
  gameLocNoindexTail: boolean;
}

let polCache: { at: number; p: SeoPolicy } | null = null;

export async function loadSeoPolicy(): Promise<SeoPolicy> {
  if (polCache && Date.now() - polCache.at < 5 * 60_000) return polCache.p;
  const num = async (k: string, d: number) => {
    const n = Number(await getSetting(k, String(d)).catch(() => String(d)));
    return Number.isFinite(n) && n >= 0 ? n : d;
  };
  const p: SeoPolicy = {
    modSitemapMinDownloads: await num("seo_mod_sitemap_min_downloads", 10_000),
    modNoindexBelowDownloads: await num("seo_mod_noindex_below_downloads", 100),
    gameLocSitemapMode: (await getSetting("seo_gameloc_sitemap_mode", "demand").catch(() => "demand")) === "all" ? "all" : "demand",
    gameLocNoindexTail: ["true", "1", "on"].includes((await getSetting("seo_gameloc_noindex_tail", "false").catch(() => "false")).toLowerCase()),
  };
  polCache = { at: Date.now(), p };
  return p;
}

let demandCache: { at: number; slugs: Set<string> } | null = null;

/**
 * Landing-page slugs (no leading slash) that received at least one human visit
 * referred by a search or AI-answer engine in the last 90 days, from our own
 * Visit table. Bot-looking user agents are excluded; this is a floor on real
 * interest, not a traffic report.
 */
export async function demandSlugs(): Promise<Set<string>> {
  if (demandCache && Date.now() - demandCache.at < 30 * 60_000) return demandCache.slugs;
  const rows = await db
    .$queryRaw<{ path: string }[]>`
      SELECT DISTINCT path FROM "Visit"
      WHERE kind = 'marketing' AND "isEntry" = true
        AND "createdAt" > now() - interval '90 days'
        AND referrer ~* '(google\\.|bing\\.|duckduckgo|yahoo\\.|ecosia|brave\\.|chatgpt|openai|perplexity|claude\\.ai|copilot|gemini)'
        AND coalesce(ua, '') !~* '(bot|crawl|spider|slurp|preview|headless|curl|python|go-http)'`
    .catch(() => [] as { path: string }[]);
  const slugs = new Set(rows.map((r) => r.path.replace(/^\/+|\/+$/g, "").split("?")[0]));
  demandCache = { at: Date.now(), slugs };
  return slugs;
}

const COMBO_BY_SLUG = new Map(GAME_LOCATION_COMBOS.map((c) => [c.slug, c]));

/** A game × location page is "core" when the location has a real Nxeon datacenter. */
export function isCoreGameLocation(slug: string): boolean {
  const c = COMBO_BY_SLUG.get(slug);
  if (!c) return true; // not a game×location combo: not ours to prune
  return (GAME_LOCATIONS_BY_SLUG.get(c.location.slug)?.presence ?? c.location.presence) === "datacenter";
}

/** Should this game × location slug be listed in the sitemap? */
export async function listGameLocationInSitemap(slug: string): Promise<boolean> {
  const pol = await loadSeoPolicy();
  if (pol.gameLocSitemapMode === "all" || isCoreGameLocation(slug)) return true;
  return (await demandSlugs()).has(slug);
}

/** Should this game × location page carry noindex? (Off unless the owner enabled it.) */
export async function gameLocationNoindex(slug: string): Promise<boolean> {
  const pol = await loadSeoPolicy();
  if (!pol.gameLocNoindexTail) return false;
  return !(await listGameLocationInSitemap(slug));
}

/** Mod noindex: only for mods with essentially no real demand signal. */
export async function modNoindex(downloads: number | null | undefined): Promise<boolean> {
  const pol = await loadSeoPolicy();
  return pol.modNoindexBelowDownloads > 0 && (downloads ?? 0) < pol.modNoindexBelowDownloads;
}
