model Plan {
  id              String        @id @default(cuid())
  slug            String        @unique
  name            String
  cpuCores        Int
  ramMB           Int
  diskGB          Int
  bandwidthTB     Float         @default(1)
  priceCents      Int
  /// LOW introductory MONTHLY price (cents) charged for the FIRST term only; the
  /// plan then RENEWS at the regular `priceCents` (classic hosting promo — e.g.
  /// "$3.99/mo first term, renews at $6.49/mo"). NULL = no intro (the plan bills
  /// `priceCents` from day one). Reused through the existing first-term-discount
  /// plumbing: the order stamps the implied first-term rate on
  /// `Server.termPromoPercent`, and every renewal path (lib/renewal-charge.ts)
  /// reads `priceCents` and knows nothing about this column, so renewal === regular
  /// by construction. Only honoured when strictly below `priceCents`.
  introPriceCents Int?
  /// How many of the first term's months are billed at `introPriceCents` before the
  /// remainder of that term reverts to the regular rate. NULL = the WHOLE first term
  /// is at the intro price (the common "$X first month, then $Y/mo" case is
  /// `introTermMonths = 1`). Ignored when `introPriceCents` is null.
  introTermMonths Int?
  storageTier     String        @default("nvme") // "nvme" | "hdd"
  active          Boolean       @default(true)
  sortOrder       Int           @default(0)
  createdAt       DateTime      @default(now())
  servers         Server[]
  gamePlans       GamePlan[]
  // NxCloud tiers that clone/size their VM from this Plan. A backing Plan for an
  // NxCloud tier is kept `active = false` so it never shows in the VPS wizard.
  nxcloudPlans    NxCloudPlan[]
}
model GamePlan {
  id           String   @id @default(cuid())
  gameFamily   String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name         String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB        Int
  cpuCores     Int      @default(2)
  diskGB       Int
  slots        Int? // player slots (nullable)
  priceCents   Int // retail price the customer pays (per term) — the REGULAR/renewal rate
  /// GRANDFATHER PROGRAM (2026-09-17): mirrors Plan.introPriceCents/introTermMonths
  /// exactly — a lower first-term price that renews at the regular `priceCents`
  /// above. Read by the same generic lib/intro-pricing.ts helpers VPS already
  /// uses (planIntroMonthlyCents/planIntroTermMonths take a `{priceCents}`-shaped
  /// row, so a GamePlan works with zero new code there). NULL introTermMonths
  /// means the WHOLE first term (any length) bills at introPriceCents.
  introPriceCents Int?
  introTermMonths Int?
  termMonths   Int      @default(1)
  basePlanId   String // the VPS Plan used to size/provision the VM
  basePlan     Plan     @relation(fields: [basePlanId], references: [id])
  osTemplateId String? // the game's OsTemplate (image) to deploy
  featured     Boolean  @default(false)
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  servers      Server[]
}
