/**
 * Internal-link graph from the sitemap: fetches every non-mod sitemap URL (and a
 * bounded sample of mods), records each page's outgoing internal links, then
 * reports in-link counts, orphans (zero in-links from other sitemap pages) and
 * click depth from the homepage.
 *   npx tsx scripts/seo-link-graph.ts --base https://nxeon.cloud [--mods 300] [--concurrency 3] [--json out.json]
 */
import { writeFileSync } from "node:fs";
import { parseHtml } from "../lib/seo-audit/parse";
import { classifyTemplate, parseSitemapXml } from "../lib/seo-audit/sitemap";

const arg = (n: string, d?: string) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : d; };
const base = (arg("base", "http://localhost:3000")!).replace(/\/$/, "");
const modSample = Number(arg("mods", "300"));
const conc = Number(arg("concurrency", "3"));
const rebase = (u: string) => { const x = new URL(u); const b = new URL(base); x.protocol = b.protocol; x.host = b.host; return x.toString(); };
const key = (u: string) => { const x = new URL(u, base); x.hash = ""; x.search = ""; const p = x.pathname.replace(/\/+$/, "") || "/"; return p; };

async function main() {
  const idx = parseSitemapXml(await (await fetch(`${base}/sitemap.xml`)).text());
  const urls: string[] = [];
  for (const c of idx.entries) {
    const u = rebase(c.loc);
    const xml = await (await fetch(u)).text();
    const es = parseSitemapXml(xml).entries.map((e) => rebase(e.loc));
    const isMod = /\/mods-\d+\.xml$|\/sitemap\/[1-9]\.xml$/.test(u) && es.some((e) => /\/mods\/[^/]+\/[^/]+$/.test(e));
    if (isMod) { const step = Math.max(1, Math.floor(es.length / Math.max(1, modSample / Math.max(1, idx.entries.length)))); urls.push(...es.filter((_, i) => i % step === 0).slice(0, Math.ceil(modSample / 4))); }
    else urls.push(...es);
  }
  const set = [...new Set(urls)];
  const inSitemap = new Set(set.map(key));
  console.error(`crawling ${set.length} pages`);
  const out = new Map<string, Set<string>>();
  let next = 0, done = 0;
  await Promise.all(Array.from({ length: conc }, async () => {
    while (next < set.length) {
      const u = set[next++];
      try {
        const r = await fetch(u, { redirect: "follow", signal: AbortSignal.timeout(30_000) });
        const links = new Set<string>();
        if (r.ok) for (const l of parseHtml(await r.text()).links) {
          if (!/^\/(?!\/)/.test(l.href) && !l.href.startsWith(base) && !l.href.startsWith("https://nxeon.cloud")) continue;
          const k = key(l.href.replace("https://nxeon.cloud", ""));
          if (k !== key(u)) links.add(k);
        }
        out.set(key(u), links);
      } catch { out.set(key(u), new Set()); }
      if (++done % 200 === 0) console.error(`${done}/${set.length}`);
    }
  }));
  const inCount = new Map<string, number>();
  for (const [from, ls] of out) for (const l of ls) if (inSitemap.has(l) && l !== from) inCount.set(l, (inCount.get(l) ?? 0) + 1);
  // BFS depth from "/"
  const depth = new Map<string, number>([["/", 0]]);
  const q = ["/"];
  while (q.length) { const c = q.shift()!; for (const l of out.get(c) ?? []) if (!depth.has(l)) { depth.set(l, depth.get(c)! + 1); q.push(l); } }
  const byT = new Map<string, { n: number; orphans: number; inSum: number; unreachable: number; depthSum: number; maxDepth: number; minIn: number }>();
  const orphans: string[] = [];
  for (const k of inSitemap) {
    if (!out.has(k)) continue; // not crawled (mod sample gaps)
    const t = classifyTemplate(k);
    const e = byT.get(t) ?? { n: 0, orphans: 0, inSum: 0, unreachable: 0, depthSum: 0, maxDepth: 0, minIn: 1e9 };
    const ic = inCount.get(k) ?? 0;
    e.n++; e.inSum += ic; e.minIn = Math.min(e.minIn, ic);
    if (ic === 0) { e.orphans++; orphans.push(k); }
    const d = depth.get(k);
    if (d == null) e.unreachable++; else { e.depthSum += d; e.maxDepth = Math.max(e.maxDepth, d); }
    byT.set(t, e);
  }
  console.log("| template | crawled | avg in-links | min in | orphans | unreachable from home | avg depth | max depth |\n|---|---|---|---|---|---|---|---|");
  for (const [t, e] of [...byT].sort((a, b) => b[1].n - a[1].n)) console.log(`| ${t} | ${e.n} | ${(e.inSum / e.n).toFixed(1)} | ${e.minIn} | ${e.orphans} | ${e.unreachable} | ${(e.depthSum / Math.max(1, e.n - e.unreachable)).toFixed(1)} | ${e.maxDepth} |`);
  console.log(`\norphans (sample): ${orphans.slice(0, 25).join(", ")}`);
  const j = arg("json"); if (j) writeFileSync(j, JSON.stringify({ byTemplate: Object.fromEntries(byT), orphans }, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });
E
