/**
 * Server-side HTML post-processing for the marketing pages: image loading
 * hints. The design package's markup ships most <img> tags without
 * loading/decoding hints, so below-the-fold images competed with the LCP image
 * for bandwidth. Rules: the first EAGER_IMAGES images in document order are left
 * alone (likely above the fold / LCP); every later <img> without a `loading`
 * attribute gets loading="lazy" decoding="async"; an <img> with no alt
 * attribute at all gets alt="" (explicitly decorative — better than absent).
 * <script> and <style> bodies are never touched (they can contain markup in JS
 * strings that must stay byte-for-byte).
 */
const EAGER_IMAGES = 2;

export function optimizeImages(html: string, eager = EAGER_IMAGES): string {
  let n = 0;
  return html
    .split(/(<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>)/i)
    .map((part, i) => {
      if (i % 2 === 1) return part; // script/style
      return part.replace(/<img\b[^>]*>/gi, (tag) => {
        n++;
        let t = tag;
        if (!/\salt\s*=/i.test(t)) t = t.replace(/^<img\b/i, '<img alt=""');
        if (n > eager && !/\sloading\s*=/i.test(t)) t = t.replace(/\s*\/?>$/, (e) => ` loading="lazy" decoding="async"${e.trim() === "/>" ? " />" : ">"}`);
        return t;
      });
    })
    .join("");
}
