cd /opt/nxeon-wt-seo && grep -n "export const ACTIVE_GAME_FAMILIES" -A3 lib/marketing/gameLocationLandings.ts | head -6; python3 - <<'E'
p='/opt/nxeon-wt-seo/lib/marketing/gameLocationLandings.ts'; s=open(p).read()
i=s.index("function gameRelatedLinks"); j=s.index("/**\n * Build the unique landing content for one (game family")
new='''/**
 * Hub/spoke internal links for a game × location page. The previous version
 * linked every page to the SAME first three locations, so the other ~700 combos
 * received almost no internal in-links (orphan tail). Now the links rotate
 * around a ring so every combo is linked from siblings: the game's hub, the real
 * datacenter locations for this game, the next three locations on the ring, and
 * the next two games at this same location. Deterministic (no randomness) so
 * the output is stable between renders.
 */
function gameRelatedLinks(combo: GameLocationCombo): { label: string; href: string }[] {
  const { location: loc, family } = combo;
  const href = (l: GameLocationDef, f: GameFamily) => `/${l.slug}-${GAME_URL_SLUG[f]}-server-hosting`;
  const li = GAME_LOCATIONS.findIndex((l) => l.slug === loc.slug);
  const fi = ACTIVE_GAME_FAMILIES.indexOf(family);
  const seen = new Set<string>([href(loc, family)]);
  const out: { label: string; href: string }[] = [{ label: `${gameName(family)} Server Hosting`, href: `/${GAME_URL_SLUG[family]}-server-hosting` }];
  const push = (label: string, h: string) => {
    if (seen.has(h)) return;
    seen.add(h);
    out.push({ label, href: h });
  };
  // the locations with a real Nxeon datacenter first — the pages most worth ranking
  for (const l of GAME_LOCATIONS.filter((x) => x.presence === "datacenter")) push(`${l.name} ${gameName(family)} Hosting`, href(l, family));
  for (let k = 1; k <= 3 && li >= 0; k++) {
    const l = GAME_LOCATIONS[(li + k) % GAME_LOCATIONS.length];
    push(`${l.name} ${gameName(family)} Hosting`, href(l, family));
  }
  for (let k = 1; k <= 2 && fi >= 0; k++) {
    const f = ACTIVE_GAME_FAMILIES[(fi + k) % ACTIVE_GAME_FAMILIES.length];
    push(`${gameName(f)} Hosting in ${loc.name}`, href(loc, f));
  }
  out.push({ label: "All game servers", href: "/game-servers" }, { label: "Pricing", href: "/pricing" });
  return out;
}

'''
