import type { Metadata } from "next";
import Link from "next/link";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { APP_URL } from "@/components/marketing/StructuredData";
import { LOCATIONS, REGIONS, SERVICES } from "@/lib/marketing/locationLandings";
import { ACTIVE_GAME_FAMILIES, GAME_LOCATIONS, GAME_URL_SLUG, GENERAL_LOCATION_SLUGS } from "@/lib/marketing/gameLocationLandings";
import { gameName } from "@/lib/games";

export const dynamic = "force-static";

export const metadata: Metadata = {
  title: "Hosting locations — VPS, game servers and web hosting by city",
  description:
    "Every location Nxeon serves, with an honest note on where its datacenters actually are: Singapore, Germany and Canada, plus the city and region pages for VPS, game server and web hosting.",
  alternates: { canonical: "/locations" },
  openGraph: { type: "website", siteName: "Nxeon", title: "Hosting locations — Nxeon", description: "VPS, game server and web hosting pages by city and region, with real datacenter locations marked.", url: `${APP_URL}/locations`, images: [{ url: "/opengraph-image" }] },
  twitter: { card: "summary_large_image", title: "Hosting locations — Nxeon", images: ["/opengraph-image"] },
};

const SERVICE_KEYS = ["vps", "game", "web"] as const;

/**
 * Crawlable hub for the programmatic location pages. Plain server-rendered
 * links (no JS needed), grouped so each page is one hop from here:
 * datacenters → regions → cities × service → game × location. Added because
 * the SEO audit found hundreds of location pages with no internal in-link at
 * all (docs/SEO-AUDIT-2026-10.md).
 */
export default function LocationsHub() {
  const datacenters = LOCATIONS.filter((l) => l.presence === "datacenter");
  const svc = SERVICES.filter((s) => (SERVICE_KEYS as readonly string[]).includes(s.key));
  const generalGame = new Set(GENERAL_LOCATION_SLUGS);
  return (
    <>
      <Section tone="base" size="md">
        <SectionTitle eyebrow="Locations" title="Hosting by location" />
        <p className="mx-auto mt-4 max-w-2xl text-center text-sm text-slate-400">
          Nxeon operates real datacenters in the places marked below. Every other city or region page describes how well that audience is served from the nearest datacenter — it never claims a local facility we don&apos;t have.
        </p>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Datacenters</h2>
        <ul className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {datacenters.map((l) => (
            <li key={l.slug} className="card">
              <div className="font-medium text-white">{l.city}</div>
              <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-sm">
                {svc.map((s) => (
                  <Link key={s.key} href={`/${l.slug}-${s.urlPart}`} className="text-brand-300 hover:underline">{s.label}</Link>
                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Regions</h2>
        <ul className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {REGIONS.map((r) => (
            <li key={r.slug} className="card">
              <div className="font-medium text-white">{r.shortLabel}</div>
              <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-sm">
                {svc.map((s) => (
                  <Link key={s.key} href={`/${r.slug}-${s.urlPart}`} className="text-brand-300 hover:underline">{s.label}</Link>
                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Cities</h2>
        <ul className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {LOCATIONS.map((l) => (
            <li key={l.slug} className="card">
              <div className="font-medium text-white">{l.city} <span className="text-xs font-normal text-slate-500">· {l.region}</span></div>
              <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-sm">
                {SERVICES.map((s) => (
                  <Link key={s.key} href={`/${l.slug}-${s.urlPart}`} className="text-slate-300 hover:text-white hover:underline">{s.label}</Link>
                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Game servers by location</h2>
        <p className="mt-2 text-sm text-slate-400">Each location has a page for every game we host.</p>
        <div className="mt-3 space-y-2">
          {GAME_LOCATIONS.map((l) => (
            <details key={l.slug} className="card">
              <summary className="cursor-pointer font-medium text-white">
                {generalGame.has(`${l.slug}-game-server-hosting`) ? (
                  <Link href={`/${l.slug}-game-server-hosting`} className="hover:underline">{l.name} game server hosting</Link>
                ) : (
                  l.name
                )}
              </summary>
              <ul className="mt-3 grid gap-1 text-sm sm:grid-cols-2 lg:grid-cols-3">
                {ACTIVE_GAME_FAMILIES.map((f) => (
                  <li key={f}>
                    <Link href={`/${l.slug}-${GAME_URL_SLUG[f]}-server-hosting`} className="text-slate-300 hover:text-white hover:underline">{gameName(f)} in {l.name}</Link>
                  </li>
                ))}
              </ul>
            </details>
          ))}
        </div>
      </Section>
    </>
  );
}
