                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Regions</h2>
        <ul className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {REGIONS.map((r) => (
            <li key={r.slug} className="card">
              <div className="font-medium text-white">{r.shortLabel}</div>
              <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-sm">
                {svc.map((s) => (
                  <Link key={s.key} href={`/${r.slug}-${s.urlPart}`} className="text-brand-300 hover:underline">{s.label}</Link>
                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Cities</h2>
        <ul className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {LOCATIONS.map((l) => (
            <li key={l.slug} className="card">
              <div className="font-medium text-white">{l.city} <span className="text-xs font-normal text-slate-500">· {l.region}</span></div>
              <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-sm">
                {SERVICES.map((s) => (
                  <Link key={s.key} href={`/${l.slug}-${s.urlPart}`} className="text-slate-300 hover:text-white hover:underline">{s.label}</Link>
                ))}
              </div>
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="base" size="sm">
        <h2 className="text-lg font-semibold text-white">Game servers by location</h2>
        <p className="mt-2 text-sm text-slate-400">Each location has a page for every game we host.</p>
        <div className="mt-3 space-y-2">
          {GAME_LOCATIONS.map((l) => (
            <details key={l.slug} className="card">
              <summary className="cursor-pointer font-medium text-white">
                {generalGame.has(`${l.slug}-game-server-hosting`) ? (
