import "server-only";
import { COMPETITORS, hubEntry, migrateRoute } from "../_data/vs-competitors";

/**
 * Plain server-rendered links for hub pages whose visible list is built by the
 * page's own JavaScript. Crawlers that don't execute JS (most AI/answer-engine
 * fetchers, and Google's first pass) otherwise see no links to the pages the
 * hub exists to point at — the SEO audit found every "<host> alternative" page
 * orphaned that way. Rendered visually hidden (sr-only) as a real <nav>, so it
 * is also a legitimate screen-reader list; it mirrors the visible board 1:1.
 */
export async function hubLinksHtml(route: string): Promise<string> {
  if (route !== "/compare") return "";
  const items: string[] = [];
  for (const c of COMPETITORS) {
    let name = c.short;
    try {
      name = (hubEntry(c) as { title?: string; competitor?: string }).title ?? c.short;
    } catch {
      /* fall back to the short name */
    }
    items.push(`<li><a href="${c.route}">${esc(name.replace(/^Nxeon vs /, "Nxeon vs "))}</a></li>`);
    const m = migrateRoute(c);
    if (m) items.push(`<li><a href="${m}">Move from ${esc(c.short)} to Nxeon</a></li>`);
  }
  return `<nav class="sr-only" aria-label="All comparison and migration pages"><h2>All comparison and migration pages</h2><ul>${items.join("")}</ul></nav>`;
}

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
