p='lib/seo-audit/sitemap.ts'; s=open(p).read()
i=s.index("/**\n * Template buckets")
new='''/**
 * Template buckets used to group scores. Order matters; first match wins.
 * Kept in one place so the audit, the admin page and the docs agree.
 * Location slugs mirror lib/marketing/{location,gameLocation}Landings.ts (kept
 * literal here so this module stays pure/importable from scripts and tests).
 */
const LOCATION_SLUGS = [
  "singapore", "southeast-asia", "south-korea", "japan", "malaysia", "indonesia", "germany", "united-kingdom", "india",
  "united-states", "north-america", "canada", "europe", "netherlands", "australia", "london", "frankfurt", "amsterdam",
  "paris", "new-york", "toronto", "los-angeles", "sydney", "tokyo", "mumbai", "dallas", "miami", "chicago", "hong-kong",
  "seoul", "dubai", "sao-paulo", "usa", "asia-pacific",
].sort((a, b) => b.length - a.length); // longest first so "united-states" beats "usa"-style prefixes
const SERVICE_PARTS = ["vps-hosting", "game-server-hosting", "web-hosting", "dedicated-server-hosting", "forex-vps-hosting", "reseller-hosting"];

export function classifyTemplate(pathname: string): string {
  const p = pathname.replace(/\\/+$/, "") || "/";
  if (p === "/") return "home";
  if (p.startsWith("/mods/")) return "mod";
  if (p === "/mods") return "mod-hub";
  if (p.startsWith("/blog/")) return "blog-post";
  if (p === "/blog") return "blog-index";
  if (p.startsWith("/tools/")) return "tool";
  if (p.startsWith("/servers/")) return "free-server";
  if (p.startsWith("/legal/")) return "legal";
  if (p === "/locations") return "hub";
  if (p.startsWith("/compare") || /^\\/vps-vs-|-alternative$|^\\/migrate-from-/.test(p)) return "comparison";
  if (/^\\/[^/]+-server-hosting\\/[^/]+$/.test(p)) return "game-region";
  const slug = p.slice(1);
  for (const loc of LOCATION_SLUGS) {
    if (!slug.startsWith(loc + "-")) continue;
    const rest = slug.slice(loc.length + 1);
    if (SERVICE_PARTS.includes(rest)) return "location-landing";
    if (rest.endsWith("-server-hosting")) return "game-location";
  }
  if (/-server-hosting$|^\\/plutonium-/.test(p)) return "game-landing";
  if (/vps|hosting|domains|business-email|block-storage|nxcloud|gaming/.test(p)) return "product";
  return "static";
}
'''
